function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};

  const chatId =
    source.chatId ||
    message.chat?.id ||
    payload.chatId ||
    '';

  const rawText = String(
    source.rawText ||
    source.text ||
    message.text ||
    message.caption ||
    payload.text ||
    ''
  ).trim();

  return { payload, message, chatId, rawText };
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function parseSheetTab(rawText) {
  const text = String(rawText || '').trim();

  // Hỗ trợ: tab Data, sheet tab Data, trang tính Data
  const match = text.match(/\b(?:tab|sheet tab|trang tinh|worksheet)\s+["'“”‘’]?([^"'“”‘’]+?)["'“”‘’]?(?:\s+(?:o|ô|cell|[A-Z]{1,3}\d+)|\s+(?:thanh|thành|=)|$)/i);
  if (!match) return '';

  return cleanName(match[1]);
}

function stripSheetTab(rawText) {
  return String(rawText || '')
    .replace(/\b(?:tab|sheet tab|trang tinh|worksheet)\s+["'“”‘’]?[^"'“”‘’]+?["'“”‘’]?(?:\s+(?=o|ô|cell|[A-Z]{1,3}\d+|thanh|thành|=)|$)/i, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const ctx = getTelegramContext(source);

const raw = ctx.rawText;
const normalized = normalize(raw);

let spreadsheetId =
  source.spreadsheetId ||
  source.sheetId ||
  source.fileId ||
  source.targetId ||
  args.spreadsheetId ||
  args.sheetId ||
  args.fileId ||
  args.targetId ||
  ctx.payload.spreadsheetId ||
  ctx.payload.sheetId ||
  ctx.payload.fileId ||
  ctx.payload.targetId ||
  '';

let sheetName = cleanName(
  source.sheetName ||
  source.targetName ||
  source.fileName ||
  source.title ||
  source.query ||
  args.sheetName ||
  args.targetName ||
  args.fileName ||
  args.title ||
  args.query ||
  ctx.payload.sheetName ||
  ctx.payload.targetName ||
  ctx.payload.fileName ||
  ctx.payload.title ||
  ctx.payload.query ||
  ''
);

let sheetTab =
  source.sheetTab ||
  args.sheetTab ||
  ctx.payload.sheetTab ||
  parseSheetTab(raw) ||
  '';

let cell = String(
  source.cell ||
  source.range ||
  source.rangeName ||
  args.cell ||
  args.range ||
  args.rangeName ||
  ctx.payload.cell ||
  ctx.payload.range ||
  ctx.payload.rangeName ||
  ''
).trim().toUpperCase();

let value = String(
  source.value ||
  args.value ||
  ctx.payload.value ||
  ''
).trim();

const patterns = [
  /^(?:cập nhật sheet|cap nhat sheet)\s+(.+?)\s+(?:ô|o|cell)\s+([A-Za-z]{1,3}\d+)\s+(?:thành|thanh|=)\s+(.+)$/i,
  /^(?:update cell(?: sheet)?)\s+(.+?)\s+([A-Za-z]{1,3}\d+)\s+(.+)$/i
];

for (const pattern of patterns) {
  const match = raw.match(pattern);
  if (match) {
    let parsedName = cleanName(match[1]);
    const parsedTab = parseSheetTab(parsedName);

    if (parsedTab) {
      sheetTab = sheetTab || parsedTab;
      parsedName = cleanName(stripSheetTab(parsedName));
    }

    sheetName = sheetName || parsedName;
    cell = cell || String(match[2] || '').toUpperCase();
    value = value || String(match[3] || '').trim();
    break;
  }
}

const hasTarget = Boolean(spreadsheetId || sheetName);
const hasContent = Boolean(cell && String(value || '').trim());



// Stage 11 exact-id safety guard
const __stage11Pick = (...values) => {
  for (const value of values) {
    if (Array.isArray(value) && value.length) return value;
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
    if (typeof value === 'boolean') return value;
  }
  return '';
};
const __stage11Source = source || {};
const __stage11Args = args || __stage11Source.args || __stage11Source.payload?.args || {};
const __stage11Payload = typeof payload !== 'undefined' ? payload : (__stage11Source.payload || {});
const __stage11IdFields = ["spreadsheetId", "sheetId", "fileId", "targetId"];
const __stage11AlsoFields = ["cell"];
const __stage11HasId = Boolean(__stage11Pick(...__stage11IdFields.map((field) =>
  __stage11Source[field] || __stage11Args[field] || __stage11Payload[field]
)));
const __stage11HasAlso = __stage11AlsoFields.length === 0 || Boolean(__stage11Pick(...__stage11AlsoFields.map((field) =>
  __stage11Source[field] || __stage11Args[field] || __stage11Payload[field]
)));
const __stage11Allowed = __stage11HasId && __stage11HasAlso;
const __stage11Response = __stage11Allowed ? '' : "Mia chưa cập nhật Google Sheet vì hành động này cần spreadsheetId cụ thể, ô cần sửa và giá trị mới. Bạn hãy tìm sheet trước rồi gửi lại kèm ID nhé.";

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text: normalized,

    spreadsheetId,
    sheetId: spreadsheetId,
    sheetName,
    query: sheetName,
    sheetTab,

    cell,
    value,

    hasTarget: Boolean(hasTarget && __stage11Allowed),
    hasContent,

    response: __stage11Response ? __stage11Response : hasTarget && hasContent
      ? ''
      : '📊 <b>Cập nhật ô trong Google Sheet</b>\n\nVí dụ:\n<code>cập nhật sheet Chi tiêu ô B2 thành 35000</code>\n<code>cập nhật sheet Chi tiêu tab Data ô B2 thành 35000</code>'
  }
}];

const source = $('Prepare Action').item.json || {};

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((item) => item.id || item.name);

if (!rows.length) {
  return [{
    json: {
      ...source,
      spreadsheetId: '',
      sheetId: '',
      found: false,
      response: 'Không tìm thấy Google Sheet phù hợp với: <b>' + escapeHtml(source.sheetName || source.targetName || source.query || '') + '</b>'
    }
  }];
}

const sheet = rows[0];

return [{
  json: {
    ...source,
    ...sheet,

    found: true,
    spreadsheetId: sheet.id || source.spreadsheetId || source.targetId || '',
    sheetId: sheet.id || source.sheetId || source.targetId || '',
    targetId: source.targetId || sheet.id || source.spreadsheetId || source.sheetId || '',
    sheetName: sheet.name || source.sheetName || source.targetName || source.query || '',
    targetName: source.targetName || sheet.name || source.sheetName || source.query || '',
    query: source.query || source.sheetName || source.targetName || '',
    webViewLink: sheet.webViewLink || source.webViewLink || '',
    mimeType: sheet.mimeType || source.mimeType || '',
    sheetTab: source.sheetTab || '',
    cell: source.cell || source.range || source.rangeName || '',
    range: source.range || source.rangeName || source.cell || '',
    rangeName: source.rangeName || source.range || source.cell || '',
    value: source.value || '',
    chatId: source.chatId || ''
  }
}];

function getJson(nodeName) {
  try {
    return $(nodeName).item.json || {};
  } catch (e) {
    return {};
  }
}

const source = {
  ...getJson('Prepare Action'),
  ...getJson('Resolve Search Result')
};
const result = $input.item.json || {};
const sheetId = source.spreadsheetId || source.sheetId || '';
const link = source.webViewLink || (sheetId ? `https://docs.google.com/spreadsheets/d/${sheetId}/edit` : '');
const updatedRange = result.updatedRange || result.updatedData?.range || '';
const shownCell = source.sheetTab ? `'${source.sheetTab}'!${source.cell || ''}` : (source.cell || '');
const shownTarget = source.sheetTab
  ? `${source.targetName || source.sheetName || 'Không rõ tên'} / tab ${source.sheetTab}`
  : (source.targetName || source.sheetName || 'Không rõ tên');

let text = `Đã cập nhật ô trong Google Sheet: ${shownTarget}`;
if (sheetId) text += `\nID: ${sheetId}`;
text += `\nÔ đã cập nhật: ${updatedRange || shownCell}`;
text += `\nGiá trị mới: ${source.value || ''}`;
if (link) text += `\nMở bảng tính: ${link}`;

return [{ json: { chatId: source.chatId || result.chatId || '', text: text.trim() } }];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
